    addTest("g.sw.requestTimeCode", "IBMDSwitcher RequestTimeCode() (settings put back after)", [](Ctx& c) {
        Com<IBMDSwitcher> o(static_cast<IBMDSwitcher*>(accessObject(c, "IBMDSwitcher"))); if (!o) c.skip("not reachable: IBMDSwitcher");
        BMDSwitcherVideoMode saveVideoMode{}; HRESULT hsVideoMode = SDK_CALL(IBMDSwitcher, o.p, GetVideoMode, &saveVideoMode);
        BMDSwitcherDownConversionMethod saveMethodForDownConvertedSD{}; HRESULT hsMethodForDownConvertedSD = SDK_CALL(IBMDSwitcher, o.p, GetMethodForDownConvertedSD, &saveMethodForDownConvertedSD);
        BMDSwitcher3GSDIOutputLevel save3GSDIOutputLevel{}; HRESULT hs3GSDIOutputLevel = SDK_CALL(IBMDSwitcher, o.p, Get3GSDIOutputLevel, &save3GSDIOutputLevel);
        BMDSwitcherColorimetryMode saveColorimetryMode{}; HRESULT hsColorimetryMode = SDK_CALL(IBMDSwitcher, o.p, GetColorimetryMode, &saveColorimetryMode);
        BMDSwitcherTimeCodeMode saveTimeCodeMode{}; HRESULT hsTimeCodeMode = SDK_CALL(IBMDSwitcher, o.p, GetTimeCodeMode, &saveTimeCodeMode);
        BOOL saveTimecodeSdiOutputEnabled{}; HRESULT hsTimecodeSdiOutputEnabled = SDK_CALL(IBMDSwitcher, o.p, GetTimecodeSdiOutputEnabled, &saveTimecodeSdiOutputEnabled);
        BOOL saveSuperSourceCascade{}; HRESULT hsSuperSourceCascade = SDK_CALL(IBMDSwitcher, o.p, GetSuperSourceCascade, &saveSuperSourceCascade);
        BOOL saveAutoVideoMode{}; HRESULT hsAutoVideoMode = SDK_CALL(IBMDSwitcher, o.p, GetAutoVideoMode, &saveAutoVideoMode);
        BOOL saveFadeToBlackEnabled{}; HRESULT hsFadeToBlackEnabled = SDK_CALL(IBMDSwitcher, o.p, GetFadeToBlackEnabled, &saveFadeToBlackEnabled);
        BOOL saveDskTallyOverrideEnabled{}; HRESULT hsDskTallyOverrideEnabled = SDK_CALL(IBMDSwitcher, o.p, GetDskTallyOverrideEnabled, &saveDskTallyOverrideEnabled);
        c.hr("call", SDK_CALL(IBMDSwitcher, o.p, RequestTimeCode));
        c.settle();
        { BMDSwitcherVideoMode v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetVideoMode, &v))) c.observe("after.VideoMode", js(v)); }
        { BMDSwitcherDownConversionMethod v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetMethodForDownConvertedSD, &v))) c.observe("after.MethodForDownConvertedSD", js(v)); }
        { BMDSwitcher3GSDIOutputLevel v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, Get3GSDIOutputLevel, &v))) c.observe("after.3GSDIOutputLevel", js(v)); }
        { BMDSwitcherColorimetryMode v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetColorimetryMode, &v))) c.observe("after.ColorimetryMode", js(v)); }
        { BMDSwitcherTimeCodeMode v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetTimeCodeMode, &v))) c.observe("after.TimeCodeMode", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetTimecodeSdiOutputEnabled, &v))) c.observe("after.TimecodeSdiOutputEnabled", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetSuperSourceCascade, &v))) c.observe("after.SuperSourceCascade", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetAutoVideoMode, &v))) c.observe("after.AutoVideoMode", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetFadeToBlackEnabled, &v))) c.observe("after.FadeToBlackEnabled", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcher, o.p, GetDskTallyOverrideEnabled, &v))) c.observe("after.DskTallyOverrideEnabled", js(v)); }
        if (SUCCEEDED(hsVideoMode)) SDK_CALL(IBMDSwitcher, o.p, SetVideoMode, saveVideoMode);
        if (SUCCEEDED(hsMethodForDownConvertedSD)) SDK_CALL(IBMDSwitcher, o.p, SetMethodForDownConvertedSD, saveMethodForDownConvertedSD);
        if (SUCCEEDED(hs3GSDIOutputLevel)) SDK_CALL(IBMDSwitcher, o.p, Set3GSDIOutputLevel, save3GSDIOutputLevel);
        if (SUCCEEDED(hsColorimetryMode)) SDK_CALL(IBMDSwitcher, o.p, SetColorimetryMode, saveColorimetryMode);
        if (SUCCEEDED(hsTimeCodeMode)) SDK_CALL(IBMDSwitcher, o.p, SetTimeCodeMode, saveTimeCodeMode);
        if (SUCCEEDED(hsTimecodeSdiOutputEnabled)) SDK_CALL(IBMDSwitcher, o.p, SetTimecodeSdiOutputEnabled, saveTimecodeSdiOutputEnabled);
        if (SUCCEEDED(hsSuperSourceCascade)) SDK_CALL(IBMDSwitcher, o.p, SetSuperSourceCascade, saveSuperSourceCascade);
        if (SUCCEEDED(hsAutoVideoMode)) SDK_CALL(IBMDSwitcher, o.p, SetAutoVideoMode, saveAutoVideoMode);
        if (SUCCEEDED(hsFadeToBlackEnabled)) SDK_CALL(IBMDSwitcher, o.p, SetFadeToBlackEnabled, saveFadeToBlackEnabled);
        if (SUCCEEDED(hsDskTallyOverrideEnabled)) SDK_CALL(IBMDSwitcher, o.p, SetDskTallyOverrideEnabled, saveDskTallyOverrideEnabled);
        c.settle();
        if (SUCCEEDED(hsVideoMode)) { BMDSwitcherVideoMode v{}; SDK_CALL(IBMDSwitcher, o.p, GetVideoMode, &v); c.expect(same(v, saveVideoMode), "VideoMode not put back"); }
        if (SUCCEEDED(hsMethodForDownConvertedSD)) { BMDSwitcherDownConversionMethod v{}; SDK_CALL(IBMDSwitcher, o.p, GetMethodForDownConvertedSD, &v); c.expect(same(v, saveMethodForDownConvertedSD), "MethodForDownConvertedSD not put back"); }
        if (SUCCEEDED(hs3GSDIOutputLevel)) { BMDSwitcher3GSDIOutputLevel v{}; SDK_CALL(IBMDSwitcher, o.p, Get3GSDIOutputLevel, &v); c.expect(same(v, save3GSDIOutputLevel), "3GSDIOutputLevel not put back"); }
        if (SUCCEEDED(hsColorimetryMode)) { BMDSwitcherColorimetryMode v{}; SDK_CALL(IBMDSwitcher, o.p, GetColorimetryMode, &v); c.expect(same(v, saveColorimetryMode), "ColorimetryMode not put back"); }
        if (SUCCEEDED(hsTimeCodeMode)) { BMDSwitcherTimeCodeMode v{}; SDK_CALL(IBMDSwitcher, o.p, GetTimeCodeMode, &v); c.expect(same(v, saveTimeCodeMode), "TimeCodeMode not put back"); }
        if (SUCCEEDED(hsTimecodeSdiOutputEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcher, o.p, GetTimecodeSdiOutputEnabled, &v); c.expect(same(v, saveTimecodeSdiOutputEnabled), "TimecodeSdiOutputEnabled not put back"); }
        if (SUCCEEDED(hsSuperSourceCascade)) { BOOL v{}; SDK_CALL(IBMDSwitcher, o.p, GetSuperSourceCascade, &v); c.expect(same(v, saveSuperSourceCascade), "SuperSourceCascade not put back"); }
        if (SUCCEEDED(hsAutoVideoMode)) { BOOL v{}; SDK_CALL(IBMDSwitcher, o.p, GetAutoVideoMode, &v); c.expect(same(v, saveAutoVideoMode), "AutoVideoMode not put back"); }
        if (SUCCEEDED(hsFadeToBlackEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcher, o.p, GetFadeToBlackEnabled, &v); c.expect(same(v, saveFadeToBlackEnabled), "FadeToBlackEnabled not put back"); }
        if (SUCCEEDED(hsDskTallyOverrideEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcher, o.p, GetDskTallyOverrideEnabled, &v); c.expect(same(v, saveDskTallyOverrideEnabled), "DskTallyOverrideEnabled not put back"); }
    });
