    addTest("g.fl.mixer.resetMasterOutPeakLevels", "IBMDSwitcherFairlightAudioMixer ResetMasterOutPeakLevels() (settings put back after)", [](Ctx& c) {
        Com<IBMDSwitcherFairlightAudioMixer> o(static_cast<IBMDSwitcherFairlightAudioMixer*>(accessObject(c, "IBMDSwitcherFairlightAudioMixer"))); if (!o) c.skip("not reachable: IBMDSwitcherFairlightAudioMixer");
        double saveMasterOutFaderGain{}; HRESULT hsMasterOutFaderGain = SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFaderGain, &saveMasterOutFaderGain);
        double saveMicTalkbackGain{}; HRESULT hsMicTalkbackGain = SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMicTalkbackGain, &saveMicTalkbackGain);
        BOOL saveMasterOutFollowFadeToBlack{}; HRESULT hsMasterOutFollowFadeToBlack = SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFollowFadeToBlack, &saveMasterOutFollowFadeToBlack);
        BOOL saveAudioFollowVideoCrossfadeTransition{}; HRESULT hsAudioFollowVideoCrossfadeTransition = SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetAudioFollowVideoCrossfadeTransition, &saveAudioFollowVideoCrossfadeTransition);
        c.hr("call", SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, ResetMasterOutPeakLevels));
        c.settle();
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFaderGain, &v))) c.observe("after.MasterOutFaderGain", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMicTalkbackGain, &v))) c.observe("after.MicTalkbackGain", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFollowFadeToBlack, &v))) c.observe("after.MasterOutFollowFadeToBlack", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetAudioFollowVideoCrossfadeTransition, &v))) c.observe("after.AudioFollowVideoCrossfadeTransition", js(v)); }
        if (SUCCEEDED(hsMasterOutFaderGain)) SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, SetMasterOutFaderGain, saveMasterOutFaderGain);
        if (SUCCEEDED(hsMicTalkbackGain)) SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, SetMicTalkbackGain, saveMicTalkbackGain);
        if (SUCCEEDED(hsMasterOutFollowFadeToBlack)) SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, SetMasterOutFollowFadeToBlack, saveMasterOutFollowFadeToBlack);
        if (SUCCEEDED(hsAudioFollowVideoCrossfadeTransition)) SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, SetAudioFollowVideoCrossfadeTransition, saveAudioFollowVideoCrossfadeTransition);
        c.settle();
        if (SUCCEEDED(hsMasterOutFaderGain)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFaderGain, &v); c.expect(same(v, saveMasterOutFaderGain), "MasterOutFaderGain not put back"); }
        if (SUCCEEDED(hsMicTalkbackGain)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMicTalkbackGain, &v); c.expect(same(v, saveMicTalkbackGain), "MicTalkbackGain not put back"); }
        if (SUCCEEDED(hsMasterOutFollowFadeToBlack)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetMasterOutFollowFadeToBlack, &v); c.expect(same(v, saveMasterOutFollowFadeToBlack), "MasterOutFollowFadeToBlack not put back"); }
        if (SUCCEEDED(hsAudioFollowVideoCrossfadeTransition)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioMixer, o.p, GetAudioFollowVideoCrossfadeTransition, &v); c.expect(same(v, saveAudioFollowVideoCrossfadeTransition), "AudioFollowVideoCrossfadeTransition not put back"); }
    });
