    addTest("g.fl.eq.reset", "IBMDSwitcherFairlightAudioEqualizer Reset() (settings put back after)", [](Ctx& c) {
        Com<IBMDSwitcherFairlightAudioEqualizer> o(static_cast<IBMDSwitcherFairlightAudioEqualizer*>(accessObject(c, "IBMDSwitcherFairlightAudioEqualizer"))); if (!o) c.skip("not reachable: IBMDSwitcherFairlightAudioEqualizer");
        BOOL saveEnabled{}; HRESULT hsEnabled = SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetEnabled, &saveEnabled);
        double saveGain{}; HRESULT hsGain = SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetGain, &saveGain);
        c.hr("call", SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, Reset));
        c.settle();
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetEnabled, &v))) c.observe("after.Enabled", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetGain, &v))) c.observe("after.Gain", js(v)); }
        if (SUCCEEDED(hsEnabled)) SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, SetEnabled, saveEnabled);
        if (SUCCEEDED(hsGain)) SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, SetGain, saveGain);
        c.settle();
        if (SUCCEEDED(hsEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetEnabled, &v); c.expect(same(v, saveEnabled), "Enabled not put back"); }
        if (SUCCEEDED(hsGain)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioEqualizer, o.p, GetGain, &v); c.expect(same(v, saveGain), "Gain not put back"); }
    });
