    addTest("g.fl.comp.reset", "IBMDSwitcherFairlightAudioCompressor Reset() (settings put back after)", [](Ctx& c) {
        Com<IBMDSwitcherFairlightAudioCompressor> o(static_cast<IBMDSwitcherFairlightAudioCompressor*>(accessObject(c, "IBMDSwitcherFairlightAudioCompressor"))); if (!o) c.skip("not reachable: IBMDSwitcherFairlightAudioCompressor");
        BOOL saveEnabled{}; HRESULT hsEnabled = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetEnabled, &saveEnabled);
        double saveThreshold{}; HRESULT hsThreshold = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetThreshold, &saveThreshold);
        double saveRatio{}; HRESULT hsRatio = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRatio, &saveRatio);
        double saveAttack{}; HRESULT hsAttack = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetAttack, &saveAttack);
        double saveHold{}; HRESULT hsHold = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetHold, &saveHold);
        double saveRelease{}; HRESULT hsRelease = SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRelease, &saveRelease);
        c.hr("call", SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, Reset));
        c.settle();
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetEnabled, &v))) c.observe("after.Enabled", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetThreshold, &v))) c.observe("after.Threshold", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRatio, &v))) c.observe("after.Ratio", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetAttack, &v))) c.observe("after.Attack", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetHold, &v))) c.observe("after.Hold", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRelease, &v))) c.observe("after.Release", js(v)); }
        if (SUCCEEDED(hsEnabled)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetEnabled, saveEnabled);
        if (SUCCEEDED(hsThreshold)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetThreshold, saveThreshold);
        if (SUCCEEDED(hsRatio)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetRatio, saveRatio);
        if (SUCCEEDED(hsAttack)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetAttack, saveAttack);
        if (SUCCEEDED(hsHold)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetHold, saveHold);
        if (SUCCEEDED(hsRelease)) SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, SetRelease, saveRelease);
        c.settle();
        if (SUCCEEDED(hsEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetEnabled, &v); c.expect(same(v, saveEnabled), "Enabled not put back"); }
        if (SUCCEEDED(hsThreshold)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetThreshold, &v); c.expect(same(v, saveThreshold), "Threshold not put back"); }
        if (SUCCEEDED(hsRatio)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRatio, &v); c.expect(same(v, saveRatio), "Ratio not put back"); }
        if (SUCCEEDED(hsAttack)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetAttack, &v); c.expect(same(v, saveAttack), "Attack not put back"); }
        if (SUCCEEDED(hsHold)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetHold, &v); c.expect(same(v, saveHold), "Hold not put back"); }
        if (SUCCEEDED(hsRelease)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioCompressor, o.p, GetRelease, &v); c.expect(same(v, saveRelease), "Release not put back"); }
    });
