    addTest("g.fl.expand.reset", "IBMDSwitcherFairlightAudioExpander Reset() (settings put back after)", [](Ctx& c) {
        Com<IBMDSwitcherFairlightAudioExpander> o(static_cast<IBMDSwitcherFairlightAudioExpander*>(accessObject(c, "IBMDSwitcherFairlightAudioExpander"))); if (!o) c.skip("not reachable: IBMDSwitcherFairlightAudioExpander");
        BOOL saveEnabled{}; HRESULT hsEnabled = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetEnabled, &saveEnabled);
        BOOL saveGateMode{}; HRESULT hsGateMode = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetGateMode, &saveGateMode);
        double saveThreshold{}; HRESULT hsThreshold = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetThreshold, &saveThreshold);
        double saveRange{}; HRESULT hsRange = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRange, &saveRange);
        double saveRatio{}; HRESULT hsRatio = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRatio, &saveRatio);
        double saveAttack{}; HRESULT hsAttack = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetAttack, &saveAttack);
        double saveHold{}; HRESULT hsHold = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetHold, &saveHold);
        double saveRelease{}; HRESULT hsRelease = SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRelease, &saveRelease);
        c.hr("call", SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, Reset));
        c.settle();
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetEnabled, &v))) c.observe("after.Enabled", js(v)); }
        { BOOL v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetGateMode, &v))) c.observe("after.GateMode", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetThreshold, &v))) c.observe("after.Threshold", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRange, &v))) c.observe("after.Range", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRatio, &v))) c.observe("after.Ratio", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetAttack, &v))) c.observe("after.Attack", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetHold, &v))) c.observe("after.Hold", js(v)); }
        { double v{}; if (SUCCEEDED(SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRelease, &v))) c.observe("after.Release", js(v)); }
        if (SUCCEEDED(hsEnabled)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetEnabled, saveEnabled);
        if (SUCCEEDED(hsGateMode)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetGateMode, saveGateMode);
        if (SUCCEEDED(hsThreshold)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetThreshold, saveThreshold);
        if (SUCCEEDED(hsRange)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetRange, saveRange);
        if (SUCCEEDED(hsRatio)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetRatio, saveRatio);
        if (SUCCEEDED(hsAttack)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetAttack, saveAttack);
        if (SUCCEEDED(hsHold)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetHold, saveHold);
        if (SUCCEEDED(hsRelease)) SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, SetRelease, saveRelease);
        c.settle();
        if (SUCCEEDED(hsEnabled)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetEnabled, &v); c.expect(same(v, saveEnabled), "Enabled not put back"); }
        if (SUCCEEDED(hsGateMode)) { BOOL v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetGateMode, &v); c.expect(same(v, saveGateMode), "GateMode not put back"); }
        if (SUCCEEDED(hsThreshold)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetThreshold, &v); c.expect(same(v, saveThreshold), "Threshold not put back"); }
        if (SUCCEEDED(hsRange)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRange, &v); c.expect(same(v, saveRange), "Range not put back"); }
        if (SUCCEEDED(hsRatio)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRatio, &v); c.expect(same(v, saveRatio), "Ratio not put back"); }
        if (SUCCEEDED(hsAttack)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetAttack, &v); c.expect(same(v, saveAttack), "Attack not put back"); }
        if (SUCCEEDED(hsHold)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetHold, &v); c.expect(same(v, saveHold), "Hold not put back"); }
        if (SUCCEEDED(hsRelease)) { double v{}; SDK_CALL(IBMDSwitcherFairlightAudioExpander, o.p, GetRelease, &v); c.expect(same(v, saveRelease), "Release not put back"); }
    });
